INSERT INTO questions (id, category, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES
-- Alertness (7)
('a1000001-0001-4000-8000-000000000001', 'Alertness', 'Before making a U-turn in the road, you should always:', 'Use the horn to warn other drivers', 'Select a higher gear than normal', 'Check for traffic behind you', 'Signal so that other drivers can slow down', 'c', 'Before making a U-turn you must check for traffic behind you. Use your mirrors and look over your shoulder to make sure the road is clear.'),
('a1000001-0001-4000-8000-000000000002', 'Alertness', 'You are driving on a motorway. You feel tired. What should you do?', 'Stop on the hard shoulder for a rest', 'Open a window and turn up the radio', 'Leave at the next service area and rest', 'Drive faster to reach your destination sooner', 'c', 'If you feel tired on a motorway, leave at the next service area and rest. Do not stop on the hard shoulder except in an emergency.'),
('a1000001-0001-4000-8000-000000000003', 'Alertness', 'When driving on a wet road, what should you do to help prevent skidding?', 'Drive in the tracks of the vehicle in front', 'Brake firmly if aquaplaning starts', 'Steer gently and avoid harsh braking', 'Use the highest gear possible', 'c', 'On wet roads steer gently and avoid harsh braking or acceleration. Sudden inputs can cause a skid.'),
('a1000001-0001-4000-8000-000000000004', 'Alertness', 'You are driving at night. When should you use full beam headlights?', 'Whenever there is no street lighting', 'On all unlit roads', 'Only when you can see the road ahead clearly and no one is in front', 'At all times on motorways', 'c', 'Use full beam on unlit roads when you can see clearly, but dip your headlights when you are following or meeting other traffic.'),
('a1000001-0001-4000-8000-000000000005', 'Alertness', 'What should you do before moving off from a parked position?', 'Flash your headlights', 'Sound your horn', 'Check all mirrors and look over your right shoulder', 'Rev the engine', 'c', 'Before moving off, check all mirrors and look over your right shoulder to check the blind spot.'),
('a1000001-0001-4000-8000-000000000006', 'Alertness', 'You are driving in heavy rain. Your steering suddenly feels light. What should you do?', 'Brake sharply to reduce speed', 'Ease off the accelerator and slow down gradually', 'Steer firmly towards the kerb', 'Apply the handbrake', 'b', 'Light steering can mean aquaplaning. Ease off the accelerator and slow down gradually. Do not brake sharply.'),
('a1000001-0001-4000-8000-000000000007', 'Alertness', 'Why is it important to scan the road well ahead?', 'To check your distance from the vehicle behind', 'To see road signs early', 'To anticipate hazards and plan your driving', 'To find a place to overtake', 'c', 'Looking well ahead helps you anticipate hazards early and plan your speed and position in good time.'),
-- Attitude (7)
('a1000002-0002-4000-8000-000000000001', 'Attitude', 'At a pelican crossing, the flashing amber light means you must:', 'Give way to pedestrians already on the crossing', 'Stop and wait for the green light', 'Give way to pedestrians waiting to cross', 'Stop even if the crossing is clear', 'a', 'Flashing amber means you must give way to pedestrians already on the crossing. If the crossing is clear you may proceed with caution.'),
('a1000002-0002-4000-8000-000000000002', 'Attitude', 'You are in a one-way street and want to turn right. Where should you position your vehicle?', 'In the left-hand lane', 'In the right-hand lane', 'In either lane depending on traffic', 'In the middle of the road', 'b', 'On a one-way street, position in the right-hand lane when turning right unless road markings show otherwise.'),
('a1000002-0002-4000-8000-000000000003', 'Attitude', 'Why should you be patient with learner drivers?', 'They may not have a full licence', 'They may drive slowly and make mistakes', 'They must display L plates', 'They are always supervised', 'b', 'Learner drivers may be inexperienced and make mistakes. Be patient and give them plenty of room.'),
('a1000002-0002-4000-8000-000000000004', 'Attitude', 'You are approaching a zebra crossing. A pedestrian is waiting to cross. You should:', 'Wave them across', 'Flash your headlights', 'Be ready to slow down and stop', 'Sound your horn to warn them', 'c', 'At a zebra crossing you must be ready to slow down and stop to let pedestrians cross. Do not wave them across as this can be dangerous.'),
('a1000002-0002-4000-8000-000000000005', 'Attitude', 'What should you do if another driver makes a mistake?', 'Flash your headlights angrily', 'Sound your horn for a long time', 'Stay calm and do not react aggressively', 'Overtake immediately to show your disapproval', 'c', 'Stay calm if another driver makes a mistake. Aggressive reactions can make situations more dangerous.'),
('a1000002-0002-4000-8000-000000000006', 'Attitude', 'You are driving behind a slow-moving vehicle on a narrow road. You should:', 'Follow closely so they speed up', 'Flash your headlights repeatedly', 'Keep a safe distance and wait for a safe place to overtake', 'Overtake even if you cannot see clearly ahead', 'c', 'Keep a safe following distance and only overtake when it is safe and legal to do so.'),
('a1000002-0002-4000-8000-000000000007', 'Attitude', 'When should you use your horn?', 'To greet other drivers', 'To tell others of your presence when they may not see you', 'In anger at other road users', 'When stationary in traffic', 'b', 'Use the horn only to warn others that you are there when they may not have seen you. Do not use it aggressively.'),
-- Safety and Your Vehicle (7)
('a1000003-0003-4000-8000-000000000001', 'Safety and Your Vehicle', 'It is important that tyres are correctly inflated because:', 'It reduces the risk of skidding', 'It reduces wear on the vehicle', 'It reduces fuel consumption', 'All of the above', 'd', 'Correct tyre pressure improves grip, reduces tyre wear and helps fuel efficiency. Check pressures regularly including the spare.'),
('a1000003-0003-4000-8000-000000000002', 'Safety and Your Vehicle', 'What is the legal minimum tread depth for car tyres?', '1.0 mm', '1.6 mm across the central three-quarters of the breadth', '2.0 mm', '3.0 mm', 'b', 'Car tyres must have at least 1.6 mm tread depth across the central three-quarters of the breadth of the tyre and around the entire circumference.'),
('a1000003-0003-4000-8000-000000000003', 'Safety and Your Vehicle', 'When should you check your engine oil level?', 'When the engine is hot', 'When the engine is cold and on level ground', 'While the engine is running', 'Only at the annual service', 'b', 'Check engine oil when the engine is cold and the vehicle is on level ground for an accurate reading.'),
('a1000003-0003-4000-8000-000000000004', 'Safety and Your Vehicle', 'What could happen if your vehicle is overloaded?', 'Better fuel economy', 'Improved handling', 'Longer stopping distances and reduced stability', 'Lower tyre wear', 'c', 'Overloading increases stopping distances, reduces stability and can cause excessive tyre wear or failure.'),
('a1000003-0003-4000-8000-000000000005', 'Safety and Your Vehicle', 'Why is it dangerous to drive with under-inflated tyres?', 'They make the steering lighter', 'They can overheat and may fail', 'They improve grip in the wet', 'They reduce fuel consumption', 'b', 'Under-inflated tyres flex more, overheat and are more likely to fail. They also increase fuel consumption.'),
('a1000003-0003-4000-8000-000000000006', 'Safety and Your Vehicle', 'When must you use headlights at night?', 'Only on unlit roads', 'Between sunset and sunrise', 'Only in built-up areas', 'Only when it is raining', 'b', 'You must use headlights between sunset and sunrise, and when visibility is seriously reduced during the day.'),
('a1000003-0003-4000-8000-000000000007', 'Safety and Your Vehicle', 'What does a red warning light showing an engine symbol usually mean?', 'The oil level is low', 'There is a fault with the engine management system', 'The coolant level is low', 'The battery is flat', 'b', 'An engine warning light usually indicates a fault with the engine management system. Have it checked as soon as possible.'),
-- Safety Margins (7)
('a1000004-0004-4000-8000-000000000004', 'Safety Margins', 'In very wet conditions, the stopping distance of a car is likely to be:', 'Unchanged', 'Halved', 'Doubled', 'At least doubled', 'd', 'In wet conditions stopping distances can be at least double those on dry roads. Reduce speed and increase the gap to the vehicle in front.'),
('a1000004-0004-4000-8000-000000000001', 'Safety Margins', 'On a dry road, what is the typical overall stopping distance at 30 mph?', '14 metres (45 feet)', '23 metres (75 feet)', '36 metres (118 feet)', '53 metres (175 feet)', 'b', 'At 30 mph the typical overall stopping distance on a dry road is about 23 metres (75 feet), made up of thinking and braking distance.'),
('a1000004-0004-4000-8000-000000000002', 'Safety Margins', 'You are driving at 70 mph on a dry motorway. What is the minimum safe time gap to the vehicle in front?', 'One second', 'Two seconds', 'Three seconds', 'Four seconds', 'b', 'In good dry conditions leave at least a two-second gap to the vehicle in front. Increase this in poor conditions.'),
('a1000004-0004-4000-8000-000000000003', 'Safety Margins', 'In icy conditions, how much could stopping distances increase compared with dry roads?', 'Twice as long', 'Up to five times as long', 'Up to ten times as long', 'They stay the same', 'c', 'On ice stopping distances can be up to ten times longer than on dry roads. Drive very slowly and leave a much larger gap.'),
('a1000004-0004-4000-8000-000000000005', 'Safety Margins', 'You are following a large vehicle. Why should you stay well back?', 'To avoid spray from its tyres', 'To see the road ahead and allow the driver to see you in their mirrors', 'To save fuel', 'To allow faster acceleration', 'b', 'Staying well back helps you see the road ahead and keeps you visible in the large vehicle driver''s mirrors.'),
('a1000004-0004-4000-8000-000000000006', 'Safety Margins', 'When driving in fog, you should leave a gap of at least:', 'One second', 'Two seconds', 'Three seconds', 'Ten seconds', 'd', 'In fog leave a much larger gap — at least ten seconds — because visibility and stopping distances are greatly reduced.'),
('a1000004-0004-4000-8000-000000000007', 'Safety Margins', 'What is the main reason for keeping a safe following distance?', 'To allow others to overtake', 'To give you time to react and stop if the vehicle ahead brakes suddenly', 'To reduce fuel consumption', 'To avoid dazzle from headlights', 'b', 'A safe following distance gives you time to see hazards and stop safely if the vehicle in front brakes suddenly.'),
-- Hazard Awareness (8)
('a1000005-0005-4000-8000-000000000001', 'Hazard Awareness', 'You are driving on a country road. What should you expect to see coming towards you on your side of the road?', 'Motorcycles', 'Bicycles', 'Pedestrians', 'Horse riders', 'd', 'On country roads horse riders are common. Slow down and be prepared to stop. Pass wide and slow when safe.'),
('a1000005-0005-4000-8000-000000000002', 'Hazard Awareness', 'You see a ball roll out into the road ahead. What should you do?', 'Continue at the same speed', 'Sound your horn and keep going', 'Slow down and be ready to stop for a child', 'Swerve into the opposite lane', 'c', 'A ball rolling into the road may be followed by a child. Slow down and be ready to stop.'),
('a1000005-0005-4000-8000-000000000003', 'Hazard Awareness', 'You are driving past parked cars. Why should you be cautious?', 'The road may be narrow', 'Children may run out from between parked cars', 'There may be roadworks', 'You may have to use the horn', 'b', 'Children can run out from between parked cars without warning. Drive slowly and be ready to stop.'),
('a1000005-0005-4000-8000-000000000004', 'Hazard Awareness', 'What is most likely to cause you to lose concentration while driving?', 'Using a mobile phone', 'Looking in mirrors', 'Checking the speedometer', 'Signalling correctly', 'a', 'Using a mobile phone is a major distraction. It is illegal to hold and use a phone while driving.'),
('a1000005-0005-4000-8000-000000000005', 'Hazard Awareness', 'You are approaching a junction where the view is blocked by parked vehicles. What should you do?', 'Sound your horn and emerge quickly', 'Edge forward slowly until you can see clearly', 'Flash your headlights and go', 'Stop well back and wait for someone to wave you out', 'b', 'Edge forward slowly at a junction with limited view until you can see clearly in both directions without putting yourself in danger.'),
('a1000005-0005-4000-8000-000000000006', 'Hazard Awareness', 'Why are motorcyclists especially hard to see?', 'They always ride in the gutter', 'They are smaller and can be hidden in blind spots', 'They do not use lights', 'They ride too fast', 'b', 'Motorcyclists are smaller and can be hidden in blind spots or behind other vehicles. Look carefully, especially at junctions.'),
('a1000005-0005-4000-8000-000000000007', 'Hazard Awareness', 'You are driving near a school at opening time. You should:', 'Sound your horn to warn children', 'Speed up to pass quickly', 'Drive slowly and watch for children crossing', 'Use full beam headlights', 'c', 'Near schools at opening and closing times, drive slowly and watch carefully for children crossing the road.'),
('a1000005-0005-4000-8000-000000000008', 'Hazard Awareness', 'What should you do when you see a vehicle with flashing amber beacons?', 'Overtake quickly before it moves', 'Be aware it may be a slow-moving or stationary hazard', 'Sound your horn', 'Ignore it if it is on the other side of the road', 'b', 'Flashing amber beacons warn that the vehicle is slow-moving or stationary and may be a hazard. Proceed with caution.'),
-- Vulnerable Road Users (7)
('a1000006-0006-4000-8000-000000000001', 'Vulnerable Road Users', 'You see a pedestrian with a dog wearing a yellow or burgundy coat. This especially warns you that the pedestrian is:', 'Deaf', 'Disabled', 'Deaf and blind', 'Blind', 'd', 'A dog wearing a yellow or burgundy coat indicates the owner is blind or partially sighted. Take extra care and be prepared to stop.'),
('a1000006-0006-4000-8000-000000000002', 'Vulnerable Road Users', 'When passing a cyclist, you should leave at least as much room as you would when overtaking a car. What is the recommended minimum passing distance at 30 mph?', '0.5 metres', '1.0 metre', '1.5 metres', '2.0 metres', 'c', 'Leave at least 1.5 metres when overtaking cyclists at up to 30 mph, and more at higher speeds or in poor conditions.'),
('a1000006-0006-4000-8000-000000000003', 'Vulnerable Road Users', 'You are turning left into a side road. A pedestrian is crossing the side road. Who has priority?', 'You, because you are turning', 'The pedestrian', 'Whoever arrives first', 'The pedestrian only if on a crossing', 'b', 'When turning into a side road you must give way to pedestrians who are already crossing or waiting to cross.'),
('a1000006-0006-4000-8000-000000000004', 'Vulnerable Road Users', 'Why should you take extra care around older pedestrians?', 'They may have poor hearing and sight', 'They always cross quickly', 'They never use crossings', 'They always wave you on', 'a', 'Older pedestrians may have reduced hearing and sight and may take longer to cross. Be patient and give them time.'),
('a1000006-0006-4000-8000-000000000005', 'Vulnerable Road Users', 'You are approaching a toucan crossing. Cyclists and pedestrians are waiting. The signal is green for them. You should:', 'Proceed because you have right of way', 'Stop and wait', 'Sound your horn to warn them', 'Edge forward slowly', 'b', 'At a toucan crossing when the signal is green for pedestrians and cyclists you must stop and wait.'),
('a1000006-0006-4000-8000-000000000006', 'Vulnerable Road Users', 'What does a flashing amber beacon on a school bus mean?', 'The bus is about to move off', 'Children may be getting on or off — drive with caution', 'The bus has broken down', 'You may overtake on the left', 'b', 'A flashing amber beacon on a school bus warns that children may be boarding or alighting. Drive slowly and with extra care.'),
('a1000006-0006-4000-8000-000000000007', 'Vulnerable Road Users', 'When should you be especially careful of motorcyclists?', 'On straight motorways', 'At junctions and when changing lanes', 'In car parks only', 'When they are behind you', 'b', 'Motorcyclists are especially vulnerable at junctions and when vehicles change lanes. Check mirrors and blind spots carefully.'),
-- Other Types of Vehicle (7)
('a1000007-0007-4000-8000-000000000001', 'Other Types of Vehicle', 'You are following a long vehicle approaching a crossroads. The driver signals to turn left. You should:', 'Overtake if you can leave plenty of room', 'Wait for the driver to finish turning', 'Assume the driver is turning left', 'Be aware the vehicle may need to swing right first', 'd', 'Large vehicles often need to swing right before turning left. Do not try to overtake on the left if the vehicle is signalling left.'),
('a1000007-0007-4000-8000-000000000002', 'Other Types of Vehicle', 'Why should you not overtake a lorry going uphill?', 'Lorries are always faster uphill', 'The lorry may slow down and you may be in a blind spot', 'Lorries have right of way uphill', 'It is illegal', 'b', 'A lorry climbing a hill may slow considerably. Overtaking uphill can be dangerous because of limited visibility and the lorry''s changing speed.'),
('a1000007-0007-4000-8000-000000000003', 'Other Types of Vehicle', 'You are driving behind a bus at a bus stop. What should you do?', 'Overtake as soon as possible', 'Wait patiently if it is signalling to pull out', 'Flash your headlights', 'Sound your horn', 'b', 'Be patient at bus stops. Give way to a bus signalling to pull out if it is safe to do so.'),
('a1000007-0007-4000-8000-000000000004', 'Other Types of Vehicle', 'A tractor is ahead on a narrow country road. You should:', 'Overtake immediately', 'Stay well back and wait for a safe place to pass', 'Flash your headlights', 'Drive close behind to encourage it to pull over', 'b', 'Stay well back from slow vehicles on narrow roads and only pass when you can see the road ahead is clear and it is safe.'),
('a1000007-0007-4000-8000-000000000005', 'Other Types of Vehicle', 'Why is it dangerous to overtake a long vehicle as it approaches a junction?', 'It may speed up', 'It may turn suddenly and you may be in its blind spot', 'It will always stop', 'It has right of way', 'b', 'Long vehicles need extra room to turn and have large blind spots. Overtaking near junctions is dangerous.'),
('a1000007-0007-4000-8000-000000000006', 'Other Types of Vehicle', 'You see a tram ahead. You must not:', 'Overtake it unless the track is clear and it is safe', 'Park on its track', 'Drive on the track when safe', 'Follow it at a safe distance', 'b', 'You must not park on tram tracks. Trams cannot steer around obstructions.'),
('a1000007-0007-4000-8000-000000000007', 'Other Types of Vehicle', 'When following a large vehicle, why should you keep well back before overtaking?', 'To get a better view of the road ahead', 'To reduce wind resistance', 'To allow the driver to see you in their door mirror only', 'To make overtaking quicker', 'a', 'Keeping well back before overtaking a large vehicle gives you a better view of the road ahead so you can judge when it is safe to pass.'),
-- Vehicle Handling (7)
('a1000008-0008-4000-8000-000000000001', 'Vehicle Handling', 'When driving in fog, you should use:', 'Main beam headlights', 'Sidelights only', 'Fog lights if visibility is seriously reduced', 'Hazard warning lights while moving', 'c', 'Use fog lights when visibility is seriously reduced (generally less than 100 metres). Switch them off when visibility improves.'),
('a1000008-0008-4000-8000-000000000002', 'Vehicle Handling', 'How can you use your vehicle''s gears to help control your speed on a long downhill gradient?', 'Stay in a high gear', 'Use a low gear and avoid prolonged heavy braking', 'Coast in neutral', 'Use the handbrake continuously', 'b', 'Use a low gear on long downhill gradients to use engine braking and help prevent brake fade from prolonged heavy braking.'),
('a1000008-0008-4000-8000-000000000003', 'Vehicle Handling', 'What is likely to happen if you coast downhill in neutral?', 'Better fuel economy and safer control', 'Less control and increased braking effort', 'The engine will stall', 'The steering will lock', 'b', 'Coasting in neutral reduces engine braking and vehicle control. You may need to brake harder to control speed.'),
('a1000008-0008-4000-8000-000000000004', 'Vehicle Handling', 'When driving on an icy road, how should you brake?', 'Brake firmly and quickly', 'Pump the brake pedal rapidly', 'Brake very gently or use low gears to slow down', 'Use the handbrake only', 'c', 'On ice brake very gently. Sudden braking can cause a skid. Use low gears to help control speed.'),
('a1000008-0008-4000-8000-000000000005', 'Vehicle Handling', 'What should you do if your vehicle starts to skid?', 'Brake harder', 'Steer into the skid and ease off the accelerator', 'Accelerate to regain grip', 'Steer sharply in the opposite direction', 'b', 'If you skid, ease off the accelerator and steer gently in the direction you want to go. Avoid harsh braking or steering.'),
('a1000008-0008-4000-8000-000000000006', 'Vehicle Handling', 'When are anti-lock brakes (ABS) most effective?', 'When you brake gently', 'When you brake firmly and steer', 'When you pump the brake pedal', 'When driving on loose gravel only', 'b', 'ABS works when you brake firmly and steer. It helps prevent wheels locking so you can maintain steering control.'),
('a1000008-0008-4000-8000-000000000007', 'Vehicle Handling', 'You are driving in strong winds. What should you do?', 'Drive faster to pass exposed areas quickly', 'Grip the steering wheel firmly and be prepared for gusts', 'Use cruise control', 'Drive close to large vehicles for shelter', 'b', 'In strong winds grip the steering wheel firmly, especially on exposed roads, and be prepared for sudden gusts.'),
-- Motorway Rules (7)
('a1000009-0009-4000-8000-000000000001', 'Motorway Rules', 'On a motorway, when should you use the hard shoulder?', 'When taking a short break', 'When traffic is moving slowly', 'In an emergency or breakdown', 'To answer your mobile phone', 'c', 'The hard shoulder is for emergencies and breakdowns only. Never use it for resting, phone calls or when traffic is slow.'),
('a1000009-0009-4000-8000-000000000002', 'Motorway Rules', 'What is the national speed limit for cars on a motorway?', '60 mph', '70 mph', '80 mph', '50 mph', 'b', 'The national speed limit for cars and motorcycles on motorways is 70 mph unless signs show otherwise.'),
('a1000009-0009-4000-8000-000000000003', 'Motorway Rules', 'When may you drive on the hard shoulder of a motorway?', 'When traffic is queuing', 'When directed by the police or traffic signs', 'To overtake slow traffic', 'When you miss your exit', 'b', 'You may only use the hard shoulder when directed by the police, traffic officers or signs, such as during active hard shoulder running schemes.'),
('a1000009-0009-4000-8000-000000000004', 'Motorway Rules', 'You miss your motorway exit. What should you do?', 'Reverse along the hard shoulder', 'Carry on to the next exit', 'Stop and turn around', 'Reverse in the left lane', 'b', 'If you miss your exit, continue to the next one. Never reverse or turn around on a motorway.'),
('a1000009-0009-4000-8000-000000000005', 'Motorway Rules', 'Which vehicles are not allowed to use the right-hand lane of a three-lane motorway?', 'Cars towing caravans', 'Motorcycles', 'Cars with a roof box', 'Dual-purpose vehicles', 'a', 'Vehicles such as cars towing caravans, goods vehicles over 7.5 tonnes and some other vehicles must not use the right-hand lane of a motorway with three or more lanes.'),
('a1000009-0009-4000-8000-000000000006', 'Motorway Rules', 'What should you do when joining a motorway from a slip road?', 'Stop at the end of the slip road', 'Give way to traffic already on the motorway and match your speed to merge safely', 'Force your way into the first gap', 'Use the hard shoulder to build up speed', 'b', 'When joining a motorway, give way to traffic on the motorway and use the slip road to match your speed and merge safely.'),
('a1000009-0009-4000-8000-000000000007', 'Motorway Rules', 'A red cross is showing above every lane on a motorway signal. What must you do?', 'Stop in your lane', 'Leave the motorway at the next exit', 'Not go beyond the signal in any lane', 'Use the hard shoulder', 'c', 'A red cross above a lane means you must not use that lane. If all lanes show a red cross, do not go beyond the signal.'),
-- Rules of the Road (7)
('a1000010-0010-4000-8000-000000000001', 'Rules of the Road', 'You are approaching a roundabout. You should give way to traffic:', 'Approaching from the left', 'Approaching from the right', 'Approaching from behind', 'Approaching from in front', 'b', 'At roundabouts in the UK give way to traffic approaching from the right unless signs or markings indicate otherwise.'),
('a1000010-0010-4000-8000-000000000002', 'Rules of the Road', 'You are at a junction with no signs or markings. Who has priority?', 'Traffic on the major road', 'Traffic on the minor road', 'Traffic turning right', 'Traffic turning left', 'a', 'At an unmarked junction, traffic on the major road has priority. Traffic on the minor road must give way.'),
('a1000010-0010-4000-8000-000000000003', 'Rules of the Road', 'When may you park on the right-hand side of a road at night?', 'On any one-way street', 'On a two-way road in a built-up area', 'On a two-way road outside a built-up area', 'Never', 'a', 'You may park on the right at night on a one-way street. On two-way roads park on the left unless signs allow otherwise.'),
('a1000010-0010-4000-8000-000000000004', 'Rules of the Road', 'What is the speed limit for cars in a built-up area unless signs show otherwise?', '20 mph', '30 mph', '40 mph', '50 mph', 'b', 'The default speed limit for cars in built-up areas in England and Wales is 30 mph unless signs show otherwise.'),
('a1000010-0010-4000-8000-000000000005', 'Rules of the Road', 'You are turning right at a junction. Where should you wait if oncoming traffic prevents you completing the turn?', 'In the middle of the junction', 'To the right of the centre line, not blocking oncoming traffic', 'On the pavement', 'In the left lane', 'b', 'When turning right, position just left of the centre of the road and wait without blocking oncoming traffic.'),
('a1000010-0010-4000-8000-000000000006', 'Rules of the Road', 'When may you use a bus lane during its hours of operation?', 'When avoiding a parked car', 'When turning left into a side road, if signs allow', 'To overtake slow traffic', 'At any time if it is quiet', 'b', 'You may only enter a bus lane when signs allow, such as when turning left into a side road within the permitted distance.'),
('a1000010-0010-4000-8000-000000000007', 'Rules of the Road', 'You are driving on a dual carriageway. When should you move back to the left-hand lane after overtaking?', 'As soon as you have passed the vehicle', 'When you can see the overtaken vehicle in your interior mirror', 'After one mile', 'Only when you reach a junction', 'b', 'Return to the left-hand lane as soon as it is safe after overtaking, when you can see the overtaken vehicle in your interior mirror.'),
-- Road and Traffic Signs (8)
('a1000011-0011-4000-8000-000000000001', 'Road and Traffic Signs', 'A circular sign with a red border usually means:', 'Warning', 'Direction', 'Prohibition', 'Information', 'c', 'Circular signs with red borders are usually prohibitory — they tell you something you must not do.'),
('a1000011-0011-4000-8000-000000000002', 'Road and Traffic Signs', 'What does a triangular sign with a red border mean?', 'Give way', 'Stop', 'Warning of a hazard ahead', 'No entry', 'c', 'Triangular signs with red borders are warning signs alerting you to a hazard ahead.'),
('a1000011-0011-4000-8000-000000000003', 'Road and Traffic Signs', 'A sign showing a red circle on a white background with a horizontal bar means:', 'No stopping', 'No entry for vehicular traffic', 'End of restriction', 'National speed limit', 'b', 'A red circle with a white horizontal bar means no entry for vehicular traffic.'),
('a1000011-0011-4000-8000-000000000004', 'Road and Traffic Signs', 'What does a circular blue sign with a white arrow pointing left mean?', 'Turn left ahead', 'One-way traffic to the left', 'Pass on the left', 'Keep left', 'b', 'A blue circular sign with a white arrow indicates one-way traffic in the direction shown.'),
('a1000011-0011-4000-8000-000000000005', 'Road and Traffic Signs', 'What does a sign with a brown background usually indicate?', 'A motorway route', 'A tourist direction or facility', 'A warning', 'A mandatory route', 'b', 'Brown signs give directions to tourist destinations and facilities.'),
('a1000011-0011-4000-8000-000000000006', 'Road and Traffic Signs', 'A rectangular sign with a blue background on a motorway shows:', 'Directions on a primary route', 'Motorway directions and distances', 'Local street names', 'Warning of roadworks', 'b', 'On motorways, blue rectangular signs show directions, distances and junction numbers.'),
('a1000011-0011-4000-8000-000000000007', 'Road and Traffic Signs', 'What does a sign showing "20" in a red circle mean?', 'Recommended speed 20 mph', 'Minimum speed 20 mph', 'Maximum speed 20 mph', 'Average speed check 20 mph', 'c', 'A number in a red circle is a maximum speed limit. You must not exceed it.'),
('a1000011-0011-4000-8000-000000000008', 'Road and Traffic Signs', 'What does a white circular sign with a diagonal black stripe on a national speed limit road mean?', 'End of motorway', 'National speed limit applies', 'No overtaking', 'Minimum speed limit', 'b', 'A white sign with a diagonal black stripe means the national speed limit applies for that class of road.'),
-- Documents (7)
('a1000012-0012-4000-8000-000000000001', 'Documents', 'A police officer asks to see your documents. You do not have them with you. You may be asked to produce them at a police station within:', '5 days', '7 days', '14 days', '21 days', 'b', 'If you cannot produce your driving licence and other required documents when asked, you must produce them at a police station within seven days.'),
('a1000012-0012-4000-8000-000000000002', 'Documents', 'When must your vehicle have a valid MOT certificate?', 'When it is over one year old', 'When it is over three years old', 'When it is over five years old', 'Only when sold', 'b', 'Most vehicles need an MOT test when they are three years old and every year after that.'),
('a1000012-0012-4000-8000-000000000003', 'Documents', 'What is the minimum insurance cover required to drive on public roads in the UK?', 'Third-party only', 'Third-party, fire and theft', 'Comprehensive', 'Any cover is optional', 'a', 'The minimum legal requirement is third-party insurance covering injury to others and damage to their property.'),
('a1000012-0012-4000-8000-000000000004', 'Documents', 'Who is responsible for ensuring a vehicle is roadworthy before driving it?', 'The manufacturer', 'The driver', 'The MOT tester', 'The insurance company', 'b', 'The driver is responsible for making sure the vehicle is roadworthy and safe before driving it.'),
('a1000012-0012-4000-8000-000000000005', 'Documents', 'Your car needs an MOT certificate. When is it valid until?', 'The date shown on the certificate', 'One year from the test date', 'Two years from the test date', 'Until the vehicle is sold', 'b', 'An MOT certificate is normally valid for one year from the date of the test.'),
('a1000012-0012-4000-8000-000000000006', 'Documents', 'What must you have before you drive on a public road?', 'A full driving licence and valid insurance', 'A passport', 'A vehicle handbook', 'A service record', 'a', 'You must have a valid driving licence and at least third-party insurance before driving on public roads.'),
('a1000012-0012-4000-8000-000000000007', 'Documents', 'When can you drive without a valid MOT certificate?', 'When driving to a pre-booked MOT test', 'When the car is less than five years old', 'When driving to work', 'Never under any circumstances', 'a', 'You may drive without a current MOT only when taking the vehicle to a pre-booked MOT test.'),
-- Accidents (7)
('a1000013-0013-4000-8000-000000000001', 'Accidents', 'At the scene of an accident, someone is unconscious. Your first priority is to:', 'Warn other traffic', 'Check for broken bones', 'Check their airway is clear', 'Give them a drink', 'c', 'The first priority is to check the airway is clear. Only move the person if their airway is blocked and you cannot clear it otherwise.'),
('a1000013-0013-4000-8000-000000000002', 'Accidents', 'You are involved in an accident where someone is injured. You must:', 'Stop and provide your details', 'Drive on if your vehicle is not damaged', 'Only report it if the police ask', 'Wait for someone else to report it', 'a', 'You must stop if you are involved in an accident where someone is injured and provide your name, address and vehicle registration.'),
('a1000013-0013-4000-8000-000000000003', 'Accidents', 'At an accident scene, when should you move an injured person?', 'Always move them off the road immediately', 'Only if there is further danger and it is necessary', 'Never move them under any circumstances', 'Only if they ask to be moved', 'b', 'Do not move injured people unless there is further danger, such as fire, and it is necessary for their safety.'),
('a1000013-0013-4000-8000-000000000004', 'Accidents', 'What should you do first if your vehicle is involved in a collision on a motorway?', 'Place a warning triangle behind the vehicle', 'Switch on hazard warning lights and stop as far to the left as possible', 'Stand in the lane to warn others', 'Attempt to move the other vehicle', 'b', 'On a motorway switch on hazard warning lights and stop as far left as possible. Leave the vehicle by the left side and move behind the barrier.'),
('a1000013-0013-4000-8000-000000000005', 'Accidents', 'An injured person is in shock. What should you do?', 'Give them hot sweet drinks', 'Keep them warm and reassure them', 'Raise their legs above their head', 'Make them walk around', 'b', 'Keep a person in shock warm and calm. Do not give food or drink. Seek medical help.'),
('a1000013-0013-4000-8000-000000000006', 'Accidents', 'When must you report an accident to the police?', 'Within 24 hours if details were not exchanged', 'Only if someone is killed', 'Only if a car is written off', 'Never if insurance details are exchanged', 'a', 'If you do not exchange details at the scene you must report the accident to the police within 24 hours.'),
('a1000013-0013-4000-8000-000000000007', 'Accidents', 'You arrive at the scene of a motorcycle accident. The rider is unconscious and lying on their back. What should you do?', 'Remove their helmet immediately', 'Only remove the helmet if they are not breathing and you are trained to do so', 'Sit them upright', 'Give them water', 'b', 'Do not remove a motorcyclist''s helmet unless they are not breathing and you have been trained in how to do it safely.'),
-- Vehicle Loading (7)
('a1000014-0014-4000-8000-000000000001', 'Vehicle Loading', 'Any load carried on a roof rack should be:', 'Loaded towards the rear of the vehicle', 'Visible in your exterior mirror', 'Securely fastened when driving', 'Covered with plastic sheeting', 'c', 'Loads on a roof rack must be securely fastened. An insecure load is dangerous to you and other road users.'),
('a1000014-0014-4000-8000-000000000002', 'Vehicle Loading', 'How should a heavy load be carried in a car?', 'Placed high on a roof rack', 'Placed mainly over the rear axle and secured', 'Held on a passenger''s lap', 'Placed on the front seat', 'b', 'Heavy loads should be placed low and mainly over the rear axle and secured to avoid affecting handling and stability.'),
('a1000014-0014-4000-8000-000000000003', 'Vehicle Loading', 'What effect can an overloaded roof rack have?', 'Improved fuel economy', 'Reduced wind resistance', 'Raised centre of gravity and affected handling', 'Better braking', 'c', 'A heavy or high load raises the centre of gravity and can make the vehicle less stable, especially when cornering or in wind.'),
('a1000014-0014-4000-8000-000000000004', 'Vehicle Loading', 'When towing a trailer, what should you check before starting a journey?', 'The trailer has no brakes', 'The load is secure and within the vehicle''s towing limit', 'The trailer is heavier than the car', 'The tyre pressures are lower on the car', 'b', 'Before towing check the load is secure, the combination is within legal and manufacturer limits and lights and brakes work correctly.'),
('a1000014-0014-4000-8000-000000000005', 'Vehicle Loading', 'You are towing a trailer on a motorway. What is the maximum speed unless signs show otherwise?', '50 mph', '60 mph', '70 mph', '40 mph', 'b', 'The maximum speed for a car towing a trailer on a motorway is 60 mph unless signs show a lower limit.'),
('a1000014-0014-4000-8000-000000000006', 'Vehicle Loading', 'What should you do if your trailer starts to swerve behind you?', 'Brake hard', 'Ease off the accelerator and slow down gradually', 'Accelerate to straighten it', 'Steer sharply in the opposite direction', 'b', 'If a trailer swerves, ease off the accelerator and slow down gradually. Do not brake harshly as this can make the sway worse.'),
('a1000014-0014-4000-8000-000000000007', 'Vehicle Loading', 'A load projects more than one metre behind your vehicle. What must you do?', 'Nothing if it is light', 'Mark it clearly and drive only in daylight', 'Mark the end clearly, usually with a red flag or marker board by day and a red light at night', 'Remove the load immediately', 'c', 'Loads projecting more than one metre behind must be clearly marked. Use a red flag or marker board by day and a red light at night.');
